using System.Reflection;
using HyperXBatteryTray.Updates;

namespace HyperXBatteryTray;

/// <summary>
/// Build identity read from assembly metadata generated by HyperXBatteryMonitor.csproj.
/// The release channel is not the user's update subscription preference.
/// </summary>
internal static class AppReleaseInfo
{
    private static readonly Assembly AppAssembly = typeof(AppReleaseInfo).Assembly;

    internal static bool IsBeta => string.Equals(
        GetMetadata("HBMReleaseChannel"), "Beta", StringComparison.Ordinal);

    internal static UpdateChannel DefaultUpdateChannel =>
        IsBeta ? UpdateChannel.Beta : UpdateChannel.Stable;

    internal static string SemanticVersion =>
        (AppAssembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
            ?? Application.ProductVersion).Split('+')[0];

    internal static string DisplayVersion
    {
        get
        {
            string version = SemanticVersion.Split('-')[0];
            if (!IsBeta)
                return version;

            // The compiled metadata is authoritative for the UI; the SemVer
            // prerelease suffix is a fallback for older/externally built packages.
            string? number = GetMetadata("HBMBetaNumber");
            if (string.IsNullOrWhiteSpace(number))
            {
                string semantic = SemanticVersion;
                int betaIndex = semantic.IndexOf("-beta.", StringComparison.Ordinal);
                if (betaIndex >= 0)
                    number = semantic[(betaIndex + "-beta.".Length)..];
            }
            return version + (string.IsNullOrWhiteSpace(number)
                ? " [BETA]"
                : $" [BETA {number}]");
        }
    }

    private static string? GetMetadata(string key) =>
        AppAssembly.GetCustomAttributes<AssemblyMetadataAttribute>()
            .FirstOrDefault(attribute => string.Equals(attribute.Key, key, StringComparison.Ordinal))
            ?.Value;
}
